/**
 * Link previews (WhatsApp, Facebook, Messenger, Instagram DMs, LinkedIn, X, Telegram, iMessage…).
 *
 * Every page gets a branded 1200×630 JPEG generated by /api/og from its own title and a real
 * clinic photo. The endpoint only takes a locale + page path and looks everything else up here,
 * so nobody can generate branded images with arbitrary text.
 */
import { getTranslations } from "next-intl/server";
import { categorySeo, pageSeo, treatmentSeo } from "@/content/seo";
import { siteUrl } from "@/content/site";
import { getTeamMember } from "@/content/team";
import { getCategory, getTreatment } from "@/content/treatments";
import { routing, type AppLocale } from "@/i18n/routing";
import { urlFor } from "@/sanity/client";
import { getPost } from "@/sanity/posts";

/**
 * Bump this after changing the card design: WhatsApp and Facebook cache previews per image URL,
 * so a new value makes them fetch the new image.
 */
export const SHARE_VERSION = "1";

export const SHARE_SIZE = { width: 1200, height: 630 } as const;

/** Absolute URL of the share image for a page. */
export function shareImageUrl(locale: AppLocale, path: string): string {
  const params = new URLSearchParams({ l: locale, p: path, v: SHARE_VERSION });
  return `${siteUrl()}/api/og?${params}`;
}

export interface ShareCard {
  eyebrow: string;
  title: string;
  subtitle?: string;
  /** A file in /public (e.g. "/images/clinic/exterior.webp") or an absolute https URL. */
  photo: string;
  tagline: string;
}

const taglines: Record<AppLocale, string> = {
  sq: "Implante dentare · Dhëmbë në një ditë · Turizëm dentar",
  it: "Impianti dentali · Denti in un giorno · Turismo dentale",
  en: "Dental implants · Same-day teeth · Dental tourism",
};

/** Section label shown above the title, by first path segment (keys under messages "nav"). */
const sectionKeys: Record<string, string> = {
  "same-day-teeth": "sameDay",
  treatments: "treatments",
  clinic: "clinic",
  "dental-tourism": "tourism",
  results: "results",
  prices: "prices",
  blog: "blog",
  book: "book",
  contact: "contact",
};

/** Photo per page; the longest matching path prefix wins. */
const photos: [prefix: string, photo: string][] = [
  ["/", "/images/team/dr-donela-dede-desk.webp"],
  ["/same-day-teeth", "/images/lab/full-arch-design.webp"],
  ["/treatments", "/images/lab/implant-bridge-design.webp"],
  ["/clinic", "/images/clinic/exterior.webp"],
  ["/clinic/dr-donela-dede", "/images/team/dr-donela-dede.webp"],
  ["/clinic/team", "/images/team/dr-donela-dede-desk.webp"],
  ["/clinic/technology", "/images/clinic/cbct.webp"],
  ["/clinic/laboratory", "/images/lab/technician-design.webp"],
  ["/clinic/environment", "/images/clinic/reception.webp"],
  ["/clinic/why-choose-us", "/images/clinic/treatment-room.webp"],
  ["/dental-tourism", "/images/clinic/lounge.webp"],
  ["/dental-tourism/discover-albania", "/images/discover/riviera.webp"],
  ["/dental-tourism/travel", "/images/clinic/exterior.webp"],
  ["/results", "/images/lab/design-closeup.webp"],
  ["/prices", "/images/clinic/treatment-room-2.webp"],
  ["/blog", "/images/lab/technician-design.webp"],
  ["/book", "/images/clinic/reception.webp"],
  ["/contact", "/images/clinic/exterior.webp"],
];

function photoFor(path: string): string {
  let best = photos[0];
  for (const entry of photos) {
    const [prefix] = entry;
    const matches = path === prefix || path.startsWith(`${prefix}/`);
    if (matches && prefix.length > best[0].length) best = entry;
  }
  return best[1];
}

/** "All-on-4 in Albania – Full Arch on 4 Implants" → title + subtitle. */
function splitTitle(seoTitle: string): { title: string; subtitle?: string } {
  const [title, ...rest] = seoTitle.split(" – ");
  const subtitle = rest.join(" – ");
  return { title, subtitle: subtitle ? subtitle[0].toLocaleUpperCase() + subtitle.slice(1) : undefined };
}

export function isLocale(value: string | null): value is AppLocale {
  return !!value && (routing.locales as readonly string[]).includes(value);
}

export async function resolveShareCard(locale: AppLocale, rawPath: string): Promise<ShareCard> {
  const path = `/${rawPath.split(/[?#]/)[0].split("/").filter(Boolean).join("/")}`;
  const segments = path.split("/").filter(Boolean);
  const t = await getTranslations({ locale });
  const sectionKey = sectionKeys[segments[0] ?? ""];
  const card: ShareCard = {
    eyebrow: sectionKey ? t(`nav.${sectionKey}`) : "Albania Dental Clinic",
    title: "Albania Dental Clinic",
    photo: photoFor(path),
    tagline: taglines[locale],
  };

  // Home: the hero line reads better than the SEO title.
  if (path === "/") {
    return {
      ...card,
      eyebrow: t("home.hero.eyebrow").split("·").pop()!.trim(),
      title: `${t("home.hero.title")} ${t("home.hero.accent")}`,
      subtitle: splitTitle(pageSeo["/"]![locale].title).subtitle,
    };
  }

  const seo = pageSeo[path as keyof typeof pageSeo]?.[locale];
  if (seo) return { ...card, ...splitTitle(seo.title) };

  if (segments[0] === "treatments" && segments.length >= 2) {
    const category = getCategory(segments[1]);
    const treatment = segments[2] ? getTreatment(segments[1], segments[2]) : undefined;
    if (treatment) {
      const s = treatmentSeo[treatment.slug]?.[locale];
      return {
        ...card,
        eyebrow: category ? t(category.labelKey) : card.eyebrow,
        ...(s ? splitTitle(s.title) : { title: t(treatment.labelKey) }),
        photo: treatment.image ?? card.photo,
      };
    }
    if (category) {
      const s = categorySeo[category.slug]?.[locale];
      return { ...card, ...(s ? splitTitle(s.title) : { title: t(category.labelKey) }), photo: category.image ?? card.photo };
    }
  }

  if (segments[0] === "blog" && segments[1]) {
    const post = await getPost(segments[1]).catch(() => null);
    if (post) {
      return {
        ...card,
        title: post.title,
        photo: post.mainImage?.asset
          ? urlFor(post.mainImage).width(560).height(630).fit("crop").format("jpg").quality(85).url()
          : card.photo,
      };
    }
  }

  if (segments[0] === "clinic" && segments[1] === "team" && segments[2]) {
    const member = getTeamMember(segments[2]);
    if (member && !/^\[.*\]$/.test(member.name)) {
      return { ...card, title: member.name, subtitle: member.role[locale], photo: member.photo ?? card.photo };
    }
  }

  return card;
}
